-- M4.7.2: Staff invitation RPCs.
--
-- All functions are SECURITY DEFINER, set an empty search_path, and derive the
-- actor, organization, and branch scope from the authenticated staff profile.
-- Raw invitation tokens are never accepted from or returned to clients; callers
-- pass the SHA-256 hex digest generated by the trusted Edge Function.
--
-- Authorization summary:
--   * Owner: invite Admin, Manager, Cashier, Kitchen Staff.
--   * Admin: invite Manager, Cashier, Kitchen Staff (never Admin).
--   * Manager, Cashier, Kitchen Staff: denied.
--   * Accept: only the authenticated account whose verified email matches the
--     invitation, holding a valid single-use token.

create or replace function private.assert_staff_invitation_admin()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_org_id uuid;
begin
  perform authz.require_staff_id();
  v_org_id := authz.current_organization_id();

  perform authz.assert_org_role(array['owner', 'admin']::text[]);
  perform authz.assert_org_can_administer(v_org_id);

  return v_org_id;
end;
$$;

revoke all on function private.assert_staff_invitation_admin() from public;

comment on function private.assert_staff_invitation_admin() is
  'Requires an active organization-scoped Owner/Admin and returns the actor organization id.';

create or replace function private.staff_invitation_json(p_invitation_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'invitationId', i.id,
    'email', i.email,
    'displayName', i.display_name,
    'roleCode', i.role_code,
    'scope', i.scope_type,
    'branchId', i.branch_id,
    'status', case
      when i.status = 'pending' and i.expires_at <= now() then 'expired'
      else i.status
    end,
    'expiresAt', i.expires_at,
    'lastSentAt', i.last_sent_at,
    'sendCount', i.send_count,
    'invitedByName', inviter.display_name,
    'createdAt', i.created_at,
    'acceptedAt', i.accepted_at,
    'revokedAt', i.revoked_at
  )
  from public.staff_invitations i
  join public.staff_profiles inviter
    on inviter.id = i.invited_by_staff_id
   and inviter.organization_id = i.organization_id
  where i.id = p_invitation_id;
$$;

revoke all on function private.staff_invitation_json(uuid) from public;

comment on function private.staff_invitation_json(uuid) is
  'Client-safe invitation JSON. Never exposes token_hash or the raw token.';

create or replace function private.mark_expired_staff_invitations(
  p_organization_id uuid,
  p_email text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.staff_invitations i
     set status = 'expired'
   where i.organization_id = p_organization_id
     and i.email = p_email
     and i.status = 'pending'
     and i.expires_at <= now();
end;
$$;

revoke all on function private.mark_expired_staff_invitations(uuid, text) from public;

create or replace function public.create_staff_invitation(
  p_email text,
  p_display_name text,
  p_role_code text,
  p_scope_type public.role_scope,
  p_branch_id uuid,
  p_token_hash_hex text,
  p_expires_at timestamptz,
  p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_staff_id uuid;
  v_org_id uuid;
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_display_name text := btrim(coalesce(p_display_name, ''));
  v_branch_org_id uuid;
  v_existing_staff_id uuid;
  v_invitation_id uuid;
begin
  v_actor_staff_id := authz.require_staff_id();
  v_org_id := private.assert_staff_invitation_admin();

  if v_email = ''
     or length(v_email) > 320
     or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  then
    perform private.raise_app_error(
      'VALIDATION_ERROR',
      'A valid email address is required'
    );
  end if;

  if v_display_name = '' or length(v_display_name) > 120 then
    perform private.raise_app_error(
      'VALIDATION_ERROR',
      'A display name between 1 and 120 characters is required'
    );
  end if;

  if p_token_hash_hex is null or p_token_hash_hex !~ '^[0-9a-f]{64}$' then
    perform private.raise_app_error(
      'VALIDATION_ERROR',
      'Invitation token hash must be 64 lowercase hex characters'
    );
  end if;

  if p_expires_at is null
     or p_expires_at <= now() + interval '5 minutes'
     or p_expires_at > now() + interval '30 days'
  then
    perform private.raise_app_error(
      'VALIDATION_ERROR',
      'Invitation expiry must be between 5 minutes and 30 days from now'
    );
  end if;

  if p_role_code is null
     or p_role_code not in ('admin', 'manager', 'cashier', 'kitchen_staff')
  then
    perform private.raise_app_error('VALIDATION_ERROR', 'Unsupported invitation role');
  end if;

  if p_role_code = 'admin'
     and not authz.has_org_role(array['owner']::text[])
  then
    perform private.raise_app_error(
      'PERMISSION_DENIED',
      'Only the Owner may invite an Admin'
    );
  end if;

  if p_scope_type is null then
    perform private.raise_app_error('VALIDATION_ERROR', 'Invitation scope is required');
  end if;

  if p_scope_type = 'organization' then
    if p_role_code <> 'admin' then
      perform private.raise_app_error(
        'VALIDATION_ERROR',
        'Manager, Cashier, and Kitchen Staff invitations require branch scope'
      );
    end if;

    if p_branch_id is not null then
      perform private.raise_app_error(
        'VALIDATION_ERROR',
        'Organization-scoped invitations must not include a branch'
      );
    end if;
  else
    if p_branch_id is null then
      perform private.raise_app_error(
        'VALIDATION_ERROR',
        'Branch-scoped invitations require a branch'
      );
    end if;

    select b.organization_id
      into v_branch_org_id
      from public.branches b
     where b.id = p_branch_id
       and b.status = 'active';

    if v_branch_org_id is distinct from v_org_id then
      perform private.raise_app_error('BRANCH_NOT_FOUND', 'Branch was not found');
    end if;
  end if;

  -- Authorized administrators may be told that the address is already a staff
  -- member in this organization. Cross-organization membership is not revealed
  -- here; acceptance enforces the one-organization-per-account invariant.
  select sp.id
    into v_existing_staff_id
    from auth.users u
    join public.staff_profiles sp on sp.auth_user_id = u.id
   where lower(u.email) = v_email
     and sp.organization_id = v_org_id
   limit 1;

  if v_existing_staff_id is not null then
    perform private.raise_app_error(
      'STAFF_ALREADY_MEMBER',
      'This email already belongs to a staff member in this organization'
    );
  end if;

  perform private.mark_expired_staff_invitations(v_org_id, v_email);

  if exists (
    select 1
      from public.staff_invitations i
     where i.organization_id = v_org_id
       and i.email = v_email
       and i.status = 'pending'
  ) then
    perform private.raise_app_error(
      'INVITATION_ALREADY_PENDING',
      'A pending invitation already exists for this email'
    );
  end if;

  begin
    insert into public.staff_invitations (
      organization_id,
      branch_id,
      email,
      display_name,
      role_code,
      scope_type,
      token_hash,
      status,
      invited_by_staff_id,
      expires_at,
      last_sent_at,
      send_count
    )
    values (
      v_org_id,
      p_branch_id,
      v_email,
      v_display_name,
      p_role_code,
      p_scope_type,
      decode(p_token_hash_hex, 'hex'),
      'pending',
      v_actor_staff_id,
      p_expires_at,
      now(),
      1
    )
    returning id into v_invitation_id;
  exception
    when unique_violation then
      perform private.raise_app_error(
        'INVITATION_ALREADY_PENDING',
        'A pending invitation already exists for this email'
      );
  end;

  perform private.audit_write(
    'staff',
    v_actor_staff_id,
    null,
    v_org_id,
    p_branch_id,
    'staff.invitation_created',
    'staff_invitation',
    v_invitation_id,
    nullif(btrim(p_reason), ''),
    jsonb_build_object(
      'role_code', p_role_code,
      'scope_type', p_scope_type,
      'branch_id', p_branch_id
    )
  );

  return private.staff_invitation_json(v_invitation_id);
end;
$$;

create or replace function public.list_staff_invitations(p_limit integer default 100)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_org_id uuid;
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 200));
begin
  v_org_id := private.assert_staff_invitation_admin();

  return jsonb_build_object(
    'invitations',
    coalesce(
      (
        select jsonb_agg(
                 private.staff_invitation_json(recent.id)
                 order by recent.created_at desc, recent.id
               )
          from (
            select i.id, i.created_at
              from public.staff_invitations i
             where i.organization_id = v_org_id
             order by i.created_at desc, i.id
             limit v_limit
          ) recent
      ),
      '[]'::jsonb
    )
  );
end;
$$;

create or replace function public.revoke_staff_invitation(
  p_invitation_id uuid,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_staff_id uuid;
  v_org_id uuid;
  v_invitation public.staff_invitations%rowtype;
begin
  v_actor_staff_id := authz.require_staff_id();
  v_org_id := private.assert_staff_invitation_admin();

  select *
    into v_invitation
    from public.staff_invitations i
   where i.id = p_invitation_id
     and i.organization_id = v_org_id
   for update;

  if not found then
    perform private.raise_app_error(
      'INVITATION_NOT_FOUND',
      'Staff invitation was not found'
    );
  end if;

  if v_invitation.status = 'accepted' then
    perform private.raise_app_error(
      'INVITATION_ALREADY_ACCEPTED',
      'An accepted invitation cannot be revoked'
    );
  end if;

  if v_invitation.status = 'revoked' then
    return jsonb_build_object(
      'invitationId', p_invitation_id,
      'status', 'already_revoked'
    );
  end if;

  update public.staff_invitations
     set status = 'revoked',
         revoked_at = now(),
         revoked_by_staff_id = v_actor_staff_id
   where id = p_invitation_id;

  perform private.audit_write(
    'staff',
    v_actor_staff_id,
    null,
    v_org_id,
    v_invitation.branch_id,
    'staff.invitation_revoked',
    'staff_invitation',
    p_invitation_id,
    nullif(btrim(p_reason), ''),
    jsonb_build_object('role_code', v_invitation.role_code)
  );

  return jsonb_build_object(
    'invitationId', p_invitation_id,
    'status', 'revoked'
  );
end;
$$;

create or replace function public.rotate_staff_invitation_token(
  p_invitation_id uuid,
  p_token_hash_hex text,
  p_expires_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_staff_id uuid;
  v_org_id uuid;
  v_invitation public.staff_invitations%rowtype;
begin
  v_actor_staff_id := authz.require_staff_id();
  v_org_id := private.assert_staff_invitation_admin();

  if p_token_hash_hex is null or p_token_hash_hex !~ '^[0-9a-f]{64}$' then
    perform private.raise_app_error(
      'VALIDATION_ERROR',
      'Invitation token hash must be 64 lowercase hex characters'
    );
  end if;

  if p_expires_at is null
     or p_expires_at <= now() + interval '5 minutes'
     or p_expires_at > now() + interval '30 days'
  then
    perform private.raise_app_error(
      'VALIDATION_ERROR',
      'Invitation expiry must be between 5 minutes and 30 days from now'
    );
  end if;

  select *
    into v_invitation
    from public.staff_invitations i
   where i.id = p_invitation_id
     and i.organization_id = v_org_id
   for update;

  if not found then
    perform private.raise_app_error(
      'INVITATION_NOT_FOUND',
      'Staff invitation was not found'
    );
  end if;

  if v_invitation.status = 'accepted' then
    perform private.raise_app_error(
      'INVITATION_ALREADY_ACCEPTED',
      'An accepted invitation cannot be resent'
    );
  end if;

  if v_invitation.status = 'revoked' then
    perform private.raise_app_error(
      'INVITATION_REVOKED',
      'A revoked invitation cannot be resent'
    );
  end if;

  if v_invitation.status = 'expired' or v_invitation.expires_at <= now() then
    update public.staff_invitations
       set status = 'expired'
     where id = p_invitation_id
       and status = 'pending';

    perform private.raise_app_error(
      'INVITATION_EXPIRED',
      'An expired invitation cannot be resent; create a new invitation'
    );
  end if;

  update public.staff_invitations
     set token_hash = decode(p_token_hash_hex, 'hex'),
         expires_at = p_expires_at,
         last_sent_at = now(),
         send_count = send_count + 1
   where id = p_invitation_id;

  perform private.audit_write(
    'staff',
    v_actor_staff_id,
    null,
    v_org_id,
    v_invitation.branch_id,
    'staff.invitation_resent',
    'staff_invitation',
    p_invitation_id,
    null,
    jsonb_build_object('send_count', v_invitation.send_count + 1)
  );

  return private.staff_invitation_json(p_invitation_id);
end;
$$;

create or replace function public.accept_staff_invitation(p_token_hash_hex text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_auth_user_id uuid := auth.uid();
  v_email text;
  v_invitation public.staff_invitations%rowtype;
  v_staff_id uuid;
  v_inviter_status public.staff_status;
  v_inviter_is_admin boolean;
  v_inviter_is_owner boolean;
  v_organization_status public.organization_status;
  v_branch_status public.branch_status;
begin
  if v_auth_user_id is null then
    perform private.raise_app_error('AUTH_REQUIRED', 'Authentication is required');
  end if;

  select lower(btrim(u.email))
    into v_email
    from auth.users u
   where u.id = v_auth_user_id;

  if v_email is null or v_email = '' then
    perform private.raise_app_error(
      'AUTH_INVALID_TOKEN',
      'The authenticated account does not have a verified email'
    );
  end if;

  if p_token_hash_hex is null or p_token_hash_hex !~ '^[0-9a-f]{64}$' then
    perform private.raise_app_error(
      'INVITATION_NOT_FOUND',
      'Staff invitation was not found'
    );
  end if;

  select *
    into v_invitation
    from public.staff_invitations i
   where i.token_hash = decode(p_token_hash_hex, 'hex')
   for update;

  if not found then
    perform private.raise_app_error(
      'INVITATION_NOT_FOUND',
      'Staff invitation was not found'
    );
  end if;

  if v_invitation.status = 'accepted' then
    perform private.raise_app_error(
      'INVITATION_ALREADY_ACCEPTED',
      'This invitation has already been accepted'
    );
  end if;

  if v_invitation.status = 'revoked' then
    perform private.raise_app_error(
      'INVITATION_REVOKED',
      'This invitation has been revoked'
    );
  end if;

  if v_invitation.status = 'expired' or v_invitation.expires_at <= now() then
    perform private.raise_app_error(
      'INVITATION_EXPIRED',
      'This invitation has expired'
    );
  end if;

  if v_invitation.email <> v_email then
    perform private.raise_app_error(
      'INVITATION_EMAIL_MISMATCH',
      'Sign in with the email address that received this invitation'
    );
  end if;

  select o.status
    into v_organization_status
    from public.organizations o
   where o.id = v_invitation.organization_id
     and o.deleted_at is null;

  if v_organization_status is null then
    perform private.raise_app_error(
      'ORGANIZATION_NOT_FOUND',
      'Organization was not found'
    );
  end if;

  if v_organization_status <> 'active' then
    perform private.raise_app_error(
      'ORGANIZATION_NOT_OPERATIONAL',
      'The organization is not accepting new staff'
    );
  end if;

  if v_invitation.branch_id is not null then
    select b.status
      into v_branch_status
      from public.branches b
     where b.id = v_invitation.branch_id
       and b.organization_id = v_invitation.organization_id;

    if v_branch_status is null then
      perform private.raise_app_error('BRANCH_NOT_FOUND', 'Branch was not found');
    end if;

    if v_branch_status <> 'active' then
      perform private.raise_app_error(
        'BRANCH_NOT_ACTIVE',
        'The invited branch is no longer active'
      );
    end if;
  end if;

  if exists (
    select 1
      from public.staff_profiles sp
     where sp.auth_user_id = v_auth_user_id
  ) then
    perform private.raise_app_error(
      'STAFF_ALREADY_MEMBER',
      'This account already belongs to an organization'
    );
  end if;

  -- The invitation is only as authoritative as the inviter's current role.
  -- Revoke and deny if the inviter lost organization administration.
  select sp.status
    into v_inviter_status
    from public.staff_profiles sp
   where sp.id = v_invitation.invited_by_staff_id
     and sp.organization_id = v_invitation.organization_id;

  select exists (
    select 1
      from public.staff_role_assignments sra
     where sra.staff_id = v_invitation.invited_by_staff_id
       and sra.organization_id = v_invitation.organization_id
       and sra.revoked_at is null
       and sra.scope_type = 'organization'
       and sra.role_code in ('owner', 'admin')
  )
    into v_inviter_is_admin;

  select exists (
    select 1
      from public.staff_role_assignments sra
     where sra.staff_id = v_invitation.invited_by_staff_id
       and sra.organization_id = v_invitation.organization_id
       and sra.revoked_at is null
       and sra.scope_type = 'organization'
       and sra.role_code = 'owner'
  )
    into v_inviter_is_owner;

  if v_inviter_status is distinct from 'active' or not v_inviter_is_admin then
    perform private.raise_app_error(
      'INVITATION_REVOKED',
      'This invitation is no longer valid'
    );
  end if;

  if v_invitation.role_code = 'admin' and not v_inviter_is_owner then
    perform private.raise_app_error(
      'PERMISSION_DENIED',
      'This invitation can no longer be accepted'
    );
  end if;

  begin
    insert into public.staff_profiles (
      auth_user_id,
      organization_id,
      display_name,
      status,
      invited_at,
      activated_at
    )
    values (
      v_auth_user_id,
      v_invitation.organization_id,
      v_invitation.display_name,
      'active',
      v_invitation.created_at,
      now()
    )
    returning id into v_staff_id;
  exception
    when unique_violation then
      perform private.raise_app_error(
        'STAFF_ALREADY_MEMBER',
        'This account already belongs to an organization'
      );
  end;

  insert into public.staff_role_assignments (
    staff_id,
    organization_id,
    role_code,
    scope_type,
    branch_id,
    assigned_by_staff_id,
    reason
  )
  values (
    v_staff_id,
    v_invitation.organization_id,
    v_invitation.role_code,
    v_invitation.scope_type,
    v_invitation.branch_id,
    v_invitation.invited_by_staff_id,
    'Accepted staff invitation'
  );

  update public.staff_invitations
     set status = 'accepted',
         accepted_at = now(),
         accepted_by_staff_id = v_staff_id
   where id = v_invitation.id;

  perform private.audit_write(
    'staff',
    v_staff_id,
    null,
    v_invitation.organization_id,
    v_invitation.branch_id,
    'staff.invitation_accepted',
    'staff_invitation',
    v_invitation.id,
    null,
    jsonb_build_object(
      'role_code', v_invitation.role_code,
      'scope_type', v_invitation.scope_type,
      'branch_id', v_invitation.branch_id
    )
  );

  return jsonb_build_object(
    'staffId', v_staff_id,
    'organizationId', v_invitation.organization_id,
    'roleCode', v_invitation.role_code,
    'scope', v_invitation.scope_type,
    'branchId', v_invitation.branch_id
  );
end;
$$;

revoke all on function public.create_staff_invitation(
  text, text, text, public.role_scope, uuid, text, timestamptz, text
) from public;
revoke all on function public.list_staff_invitations(integer) from public;
revoke all on function public.revoke_staff_invitation(uuid, text) from public;
revoke all on function public.rotate_staff_invitation_token(uuid, text, timestamptz) from public;
revoke all on function public.accept_staff_invitation(text) from public;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'grant execute on function public.create_staff_invitation(text, text, text, public.role_scope, uuid, text, timestamptz, text) to authenticated';
    execute 'grant execute on function public.list_staff_invitations(integer) to authenticated';
    execute 'grant execute on function public.revoke_staff_invitation(uuid, text) to authenticated';
    execute 'grant execute on function public.rotate_staff_invitation_token(uuid, text, timestamptz) to authenticated';
    execute 'grant execute on function public.accept_staff_invitation(text) to authenticated';
  end if;

  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.create_staff_invitation(text, text, text, public.role_scope, uuid, text, timestamptz, text) to service_role';
    execute 'grant execute on function public.list_staff_invitations(integer) to service_role';
    execute 'grant execute on function public.revoke_staff_invitation(uuid, text) to service_role';
    execute 'grant execute on function public.rotate_staff_invitation_token(uuid, text, timestamptz) to service_role';
  end if;
end
$$;

comment on function public.create_staff_invitation(
  text, text, text, public.role_scope, uuid, text, timestamptz, text
) is
  'Creates a pending invitation. Owner may invite any assignable role; Admin may invite Manager, Cashier, or Kitchen Staff.';
comment on function public.list_staff_invitations(integer) is
  'Lists recent invitations for the caller organization. Owner/Admin only. Never returns token hashes.';
comment on function public.revoke_staff_invitation(uuid, text) is
  'Revokes a pending or expired invitation. Accepted invitations cannot be revoked.';
comment on function public.rotate_staff_invitation_token(uuid, text, timestamptz) is
  'Rotates the acceptance token and extends expiry for resend. Pending invitations only.';
comment on function public.accept_staff_invitation(text) is
  'Single-use acceptance. Requires the authenticated account email to match the invitation and revalidates the inviter current authority.';
